  const r = clone(gresBase.norm.record), p = clone(gresBase.parsed); mutate(r, p); const v = validate(r, p, { krv }); ok(!v.ok && v.errors.some((e) => e.startsWith(expectId)), "expected " + expectId + ", got " + JSON.stringify(v.errors)); return ["rejected with " + v.errors.filter((e) => e.startsWith(expectId))[0].slice(0, 120)];
