t("N12", "fail-closed on the real ingest path: a broken note never replaces the last known good projection", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "jbc-pl-")), mir = path.join(dir, "mirror"), dd = path.join(dir, "data"); fs.mkdirSync(path.join(mir, "브엘세바"), { recursive: true }); fs.mkdirSync(path.join(mir, "그랄"), { recursive: true }); fs.mkdirSync(dd);
  fs.writeFileSync(path.join(mir, "브엘세바", path.basename(SOURCE)), srcText.replace("stable_id: JBC-CR-PLACE-BEERSHEBA-001", "stable_id: WRONG")); fs.copyFileSync(GERAR, path.join(mir, "그랄", path.basename(GERAR)));
  fs.copyFileSync(dataFile, path.join(dd, "projection.research.js")); fs.copyFileSync(idxFile, path.join(dd, "scripture.index.js"));
  const vm0 = require("vm"), beforeBox = { window: {} }; vm0.runInNewContext(fs.readFileSync(path.join(dd, "projection.research.js"), "utf8"), beforeBox); const beforeRec = clone(beforeBox.window.BVC_PROJECTION.places["JBC-CR-PLACE-BEERSHEBA-001"]);
  const before = [sha(dataFile), sha(idxFile)], r = ingest({ krv, vault: false, mirrorRoot: mir, dataDir: dd, outDir: dir, syncFile: path.join(dir, "sync.json"), writeArtifacts: false });
  const bs = r.records.find((x) => /BEERSHEBA/.test(x.document_id)), gr = r.records.find((x) => /GERAR/.test(x.document_id)); ok(bs && !bs.ok && bs.preserved_last_known_good && gr && gr.ok, "beersheba rejected + preserved, gerar still projected: " + JSON.stringify(r.records.map((x) => [x.document_id, x.ok])));
  const now = require("vm"); const box = { window: {} }; now.runInNewContext(fs.readFileSync(path.join(dd, "projection.research.js"), "utf8"), box); const kept = box.window.BVC_PROJECTION.places["JBC-CR-PLACE-BEERSHEBA-001"]; ok(JSON.stringify(kept) === JSON.stringify(beforeRec), "last known good Beersheba entry must be kept unchanged");
  ok([sha(dataFile), sha(idxFile)].join() === before.join(), "the real data files were modified"); return ["errors=" + bs.errors.join(" | ").slice(0, 200), "preserved=" + r.preserved_last_known_good];
});

t("O01", "Obsidian syntax: YAML frontmatter, [[wikilink|alias]] and ![[embed]] are handled without changing the note", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "jbc-ob-")), f = path.join(dir, "n.md"); fs.writeFileSync(f, "---\ntitle: Test\ntags: [a]\nlist:\n  - x\n---\n# H\nSee [[Some Note|alias]] and [[Plain]] ![[img.png]] end.\n\n```yaml\nk: v\nn:\n  - 1\n  - two\n```\n");
  const p = parseNote(f); ok(p.frontmatter && p.frontmatter.title === "Test" && p.frontmatter.list[0] === "x", "frontmatter"); const h = p.sections["H"]; ok(h.text[0] === "See alias and Plain end.", "wikilinks: " + h.text[0]); ok(h.yaml[0].data.k === "v" && h.yaml[0].data.n[1] === "two", "yaml block"); ok(sha(f) === p.source.sha256, "hash"); return ["frontmatter+wikilinks+yaml ok"];
});

