const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "jbc-media-")), withOverlay = (f) => { const o = clone(overlay); f(o); const file = path.join(tmp, "overlay-" + Math.random().toString(36).slice(2) + ".json"); fs.writeFileSync(file, JSON.stringify(o)); return file; };
const baseSync = path.join(tmp, "base-sync.json"); fs.writeFileSync(baseSync, JSON.stringify({ records: { [rec.stable_id]: Object.fromEntries(rec.media.map((a) => [a.id, a.content_hash])) } }));
t("M01", "expected result: discovered 3, bound 3, structured rights cleared, resolver previews enabled, payloads / invented URLs / unsafe / source mutations 0", () => { const r = run({ dryRun: true, krv, syncFile: baseSync }).mediaReport; const exp = { discovered: 3, bound: 3, rights_validated: 3, attribution_only: 0, preview_urls: 3, images_enabled: 3, resolved: 3, quarantined: 0, image_payloads: 0, invented_urls: 0, invented_preview_urls: 0, unsafe_payloads: 0, source_mutations: 0 }; ok(Object.keys(exp).every((k) => r[k] === exp[k]), JSON.stringify(r)); return [JSON.stringify(exp)]; });
t("M02", "bindings are explicit: each asset carries a target_ref (overlay_explicit) that resolves to a record id; none inferred", () => { const ids = new Set([rec.stable_id].concat(rec.candidates.map((c) => c.id))); ok(rec.media.every((a) => a.target_ref && ids.has(a.target_ref.ref) && a.target_ref.binding === "overlay_explicit"), "binding"); ok(rec.media.map((a) => a.target_ref.ref).join() === "JBC-CR-SITE-TEL_BEER_SHEVA-001,JBC-CR-SITE-TEL_BEER_SHEVA-001,JBC-CR-PLACE-BEERSHEBA_MODERN-001", "targets"); return rec.media.map((a) => a.id + " -> " + a.target_ref.ref); });
t("M03", "rights normalized per exact declared license and cleared only through the resolver", () => { const c = rec.media.map((a) => a.rights.license_code + "/sa=" + a.rights.share_alike); ok(c.join() === "CC-BY-SA-4.0/sa=true,CC-BY-SA-3.0/sa=true,CC-BY-4.0/sa=false", c.join()); ok(rec.media.every((a) => a.declared_rights.status === "CLEARED" && a.declared_rights.license === a.license && a.rights.validated && a.rights.attribution_required && a.rights.display_clearance === true && a.rights.status === "CLEARED" && a.rights.clearance_basis.resolver === "wikimedia_commons_api"), "clearance"); return c; });
