const spatialBlocks = () => { const blk = (f, a, b) => { const t0 = fs.readFileSync(f, "utf8"), i = t0.indexOf(a), j = t0.indexOf(b, i); return i >= 0 && j > i ? t0.slice(i, j) : ""; }; return { normalize: blk(path.join(__dirname, "normalize.js"), "<spatial-binding>", "</spatial-binding>") + blk(path.join(__dirname, "normalize.js"), "function siteMarker", "function normalize(parsed"), validate: blk(path.join(__dirname, "validate.js"), "V36: spatial read model", "approval + identity expectations"), app: blk(path.join(ROOT, "app.js"), "<spatial-binding>", "</spatial-binding>") }; };
t("S01", "one generic spatial read model for every record (same schema, same keys, produced by the same code)", () => { ok(BS.spatial && G.spatial && BS.spatial.schema === "JBC_SPATIAL_READ_MODEL_v0.1" && G.spatial.schema === BS.spatial.schema, "schema"); ok(Object.keys(BS.spatial).join() === Object.keys(G.spatial).join(), "same keys: " + Object.keys(BS.spatial)); ok(BS.spatial.subject.stable_id === BS.stable_id && G.spatial.subject.stable_id === G.stable_id && BS.spatial.subject.kind === "Place", "spatial identity = the research stable_id"); return ["keys=" + Object.keys(G.spatial).join(",")]; });
